import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
print('TOP LEVEL KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k,json.dumps(v))
c=r['context']
print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k"'!='"'history':
  s=json.dumps(v)
  print(k,s if len(s)<19000 else s[:19000]+' [truncated]')
print('HISTORY SUMMARY')
for t in c['history']:
 print(json.dumps({k:v for k,v in t.items() if k not in ['validation','config','candidate_diagnostics'] }|{'config':t.get('config'),'auc':t.get('validation',{}).get('auc'),'logloss':t.get('validation',{}).get('logloss'),'diagnostics':t.get('candidate_diagnostics')}))
PY"

