import ast,hashlib,json,subprocess
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
def validate(v,s):
 kind=s.get('type')
 if kind=='object':
  assert isinstance(v,dict)
  assert set(s.get('required',[]))<=set(v)
  if s.get('additionalProperties') is False:assert set(v)<=set(s.get('properties',{}))
  for key,value in v.items():
   if key in s.get('properties',{}):validate(value,s['properties'][key])
 elif kind=='array':
  assert isinstance(v,list) and len(v)>=s.get('minItems',0)
  for item in v:validate(item,s.get('items',{}))
 elif kind=='string':assert isinstance(v,str) and len(v)>=s.get('minLength',0)
 if 'enum' in s:assert v in s['enum']
 if 'const' in s:assert v==s['const'] and type(v)==type(s['const'])
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert len(p['variants'])==3
for v in p['variants']:
 path=Path(v['file']);ast.parse(path.read_text(),filename=v['file'])
 note=json.loads(v['note'])
 assert note['source_sha256']==hashlib.sha256(path.read_bytes()).hexdigest()
 assert note['config_sha256']==hashlib.sha256(json.dumps(v['config'],sort_keys=True,separators=(',',':')).encode()).hexdigest()
 assert note['protocol_hash']==p['study']['protocol_ref']
first=json.loads(p['variants'][0]['note'])['append_only_preparation_record']
assert first['study']==p['study'] and first['knowledge_assessments']==p['knowledge_assessments']
assert first['checks']['diagnostics'].startswith('42 ')
assert {a['knowledge_id'] for a in p['knowledge_assessments']} >= {'taac2026-academic-1-craft','taac2026-academic-2-unidac','taac2026-academic-3-unitokenformer','taac2026-industry-1-queryformer','taac2026-industry-2-unidot'}
assert hashlib.sha256(Path('candidate.py').read_bytes()).hexdigest()=='01e410b5ceedadc13edb3a2e5132500b7e19a24a5f0a89ddf4ab2c4cc2cda958'
print('Final validation PASS: study schema, three standalone modules, source/config hashes, preserved incumbent, receipt provenance, all five industry assessments.')
print('New model outcomes: pending authorized host execution. No training or installation performed.')
PY"

